// Função para determinar quais turmas buscar com base nos filtros
function determineTurmas($conn, $filters) {
    $gre = isset($filters['gre']) ? $filters['gre'] : [];
    $escola = isset($filters['escola']) ? $filters['escola'] : [];
    $professor = isset($filters['professor']) ? $filters['professor'] : [];
    $turma = isset($filters['turma']) ? $filters['turma'] : [];

    // Inicializar variáveis
    $types = '';
    $params = [];
    $where_clauses = [];

    if (!empty($turma)) {
        // Se turmas estão selecionadas, buscar apenas elas
        $turma_clause = createInClause('id', $turma, $conn, $types, $params);
        $where_clauses[] = $turma_clause;
    } else {
        if (!empty($professor)) {
            // Se professores estão selecionados, buscar turmas desses professores
            $professor_clause = createInClause('professor', $professor, $conn, $types, $params);
            $where_clauses[] = $professor_clause;
        }

        if (!empty($escola)) {
            // Se escolas estão selecionadas, buscar turmas dessas escolas
            $escola_clause = createInClause('escola', $escola, $conn, $types, $params);
            $where_clauses[] = $escola_clause;
        }

        if (!empty($gre)) {
            // Se GREs estão selecionados, buscar turmas desses GREs
            $gre_clause = createInClause('gre', $gre, $conn, $types, $params);
            $where_clauses[] = $gre_clause;
        }
    }

    // Montar a cláusula WHERE
    $where = '';
    if (!empty($where_clauses)) {
        $where = 'WHERE ' . implode(' AND ', $where_clauses);
    }

    // Preparar e executar a consulta
    $sql = "SELECT * FROM turmas $where";
    $stmt = $conn->prepare($sql);
    if ($stmt === false) {
        die("Erro na preparação da consulta: " . htmlspecialchars($conn->error, ENT_QUOTES, 'UTF-8'));
    }

    if (!empty($params)) {
        $stmt->bind_param($types, ...$params);
    }

    $stmt->execute();
    $result = $stmt->get_result();
    $stmt->close();

    // Retornar os resultados
    return $result;
}

// Determinar quais turmas buscar com base nos filtros
if (isset($_GET['gre']) || isset($_GET['escola']) || isset($_GET['professor']) || isset($_GET['turma'])) {
