                placeholder: '--Selecione--',
                allowClear: true
            });

            // Função para lidar com "Selecionar Tudo"
            function handleSelectAll(element) {
                element.on('select2:select', function(e) {
                    if (e.params.data.id === 'all') {
                        let allOptions = element.find('option').map(function() { return $(this).val(); }).get();
                        // Remover 'all' da lista
                        allOptions = allOptions.filter(function(value) { return value !== 'all'; });
                        element.val(allOptions).trigger('change');
                    }
                });

                element.on('select2:unselect', function(e) {
                    if (e.params.data.id === 'all') {
                        // Não fazer nada quando 'all' é desmarcado
                        // Isso impede que o backend trate 'all' como uma opção válida
                    }
                });
            }

            // Aplicar a função aos selects
            handleSelectAll($('#gre'));
            handleSelectAll($('#escola'));
            handleSelectAll($('#professor'));
            handleSelectAll($('#turma'));

            // Lógica para habilitar/desabilitar campos com base nas seleções
            $('#gre').change(function() {
                if ($(this).val() && $(this).val().length > 0) {
                    $('#escola').prop('disabled', false);
                } else {
                    $('#escola').prop('disabled', true).val(null).trigger('change');
                    $('#professor').prop('disabled', true).val(null).trigger('change');
                    $('#turma').prop('disabled', true).val(null).trigger('change');
